import{_ as a,c as l,g as e,o as n}from"./chunks/framework.CCxIPCIe.js";const m=JSON.parse('{"title":"四三六","description":"","frontmatter":{"title":"四三六","date":"2026-09-09T13:20:08.928Z","length":"794字","time":"3分钟","aside":false,"hash":-1842224723},"headers":[],"relativePath":"idea/436.md","filePath":"idea/436.md"}'),s={name:"idea/436.md"};function i(r,t,o,p,d,c){return n(),l("div",null,t[0]||(t[0]=[e("p",null,"gpt 证否了 NS 方程猜想，于是又出现了很多 ai 末日论的声音。",-1),e("p",null,"任何时代都有末日论，从道德经里的大道废有大伪，庄子里的道术为天下裂，到什么上帝已死、哲学已死，再到现在的数学终结。每一次末日论的兴起，都源于一种旧时代的共识的瓦解，引起符号体系的动荡，简言之革命。",-1),e("p",null,"符号系统没有办法消化掉这种新兴的存在，表现为精神的焦虑。但这种焦虑仅仅属于旧时代的精神，因为新时代的精神从旧时代的裂缝中破壳而出，把它作为不言而喻的东西。只是现在这种革命来的太多太频繁，以至于新时代的精神都还未站稳脚跟，就迅速过时了。",-1),e("p",null,"这些宣扬 AI 末日论的人如何夸赞 AI 超越人类都不为过，但他们必须同时记得，所有对 AI 的认可，本身都是通过人类的主体间网络进行的。也就是说，哪怕出现一个超越人类的 AGI，它也必须被人类的符号系统所捕获才能得到承认。这就回到了那个经典的康德问题，超越人类认识的物自体到底是个什么东西？",-1),e("p",null,"无论他们怎样用 ai 来否定人类，他们依然是在使用他们所试图用 AI 来否定的东西肯定着 AI。更何况这种否定如此轻浮，没有经过丝毫反思，只是顺着自己焦灼的情绪，把这种焦虑排除到体外，正如主体所遭遇的一切情绪一样，是再熟悉不过的操作。他们任由这种情绪在脑内自激回响，不断发散、扩张，直到推到一个末日论才能停下。这种终结带给他们一种安全感，他们终于可以在能指链上停下，不再受焦虑的折磨。",-1),e("p",null,"AI 的出现使得这种轻浮的否定变的太容易，他只需要召唤一个被他人承认的替身，就可以把自己所应付出努力做出的一切论断外包出去，仿佛这种否定真是他自己做出的一般。然而，他仅仅是把这种外在于自己的物质力量恬不知耻的据为己有，变成他自己化解焦虑的工具。AI 可以为他效劳，做这样或那样的精神对抗，使他的精神永远立于不败之地。AI 明明撕开了旧符号秩序的裂缝，他们却不能将这种颠覆性贯彻到底，立马要用它缝合出新的封闭系统，在其中千秋万代。显然这个新系统仅仅存在于他的脑海中。在试图将所有人囊括于这个封闭系统的绝对统治之前，他不得不面对那具正在产生着焦虑的肉身，因为最直接的问题是，你今天要怎样生活？这是 ai 无法替你效劳的。",-1)]))}const _=a(s,[["render",i]]);export{m as __pageData,_ as default};
